// Canonical source: packages/rules/src/. Edit there, then re-run the script.

// Combat events -> the lines the TABLE reads (F09, 2026-08-01).
//
// The Lab already renders events, and that formatter cannot be reused here: it prints the target's
// AC on every attack and both sides' exact HP on every hit. In a DM tool that is the point; in play
// it is the same redaction leak as the forecast card. So this is a second, player-facing rendering
// of the same events - deterministic, no model in the loop - and it is built server-side, which is
// what keeps enemy numbers behind the edge function instead of shipped-then-hidden.
//
// The rule (2026-07-22): party numbers exact, enemy numbers never. An enemy's condition is a band
// ("bloodied"), an enemy's AC and attack list do not appear at all.

import { hpBandLabel } from './redaction.ts'
import type { CombatEvent } from './types.ts'

export interface RecapContext {
  /** Engine combatant id -> display name. */
  name: (id: string) => string
  /** True for the party's own side, whose numbers are shown exactly. */
  isParty: (id: string) => boolean
}

function hpNote(ctx: RecapContext, id: string, hp: { current: number; max: number }): string {
  return ctx.isParty(id) ? `${hp.current}/${hp.max}` : hpBandLabel(hp.current, hp.max)
}

/**
 * One event -> one line, or null for events that would only add noise at the table (initiative
 * order, turn bookkeeping, and every roll breakdown - the numbers behind a hit are DM detail).
 */
export function recapLine(event: CombatEvent, ctx: RecapContext): string | null {
  switch (event.kind) {
    case 'round_start':
      return `-- Round ${event.round} --`
    case 'turn_skip':
      return `${event.name} is ${event.reason} - their turn passes.`
    case 'move':
      return `${ctx.name(event.id)} moves ${event.cost} square${event.cost === 1 ? '' : 's'}.`
    case 'attack': {
      const who = ctx.name(event.attackerId)
      const target = ctx.name(event.targetId)
      const opportunity = event.reaction ? ' as they withdraw' : ''
      if (event.outcome === 'miss') return `${who} attacks ${target} with ${event.attackName}${opportunity} - miss.`
      const crit = event.outcome === 'crit' ? ' Critical hit!' : ''
      return `${who} hits ${target} with ${event.attackName}${opportunity}.${crit}`
    }
    case 'damage':
      return `${ctx.name(event.id)} takes ${ctx.isParty(event.id) ? `${event.amount} damage` : 'a hit'} (${hpNote(ctx, event.id, event.hp)}).`
    case 'heal':
      return `${ctx.name(event.id)} recovers ${event.amount} (${hpNote(ctx, event.id, event.hp)}).`
    case 'spell_cast': {
      const who = event.targets.length > 0 ? event.targets.map((t) => t.name).join(', ') : 'no one'
      return `${event.casterName} casts ${event.spellName} at ${who}.`
    }
    case 'save':
      return `${event.name} ${event.success ? 'shrugs it off' : 'is caught full-on'}.`
    case 'down':
      return `${event.name} ${event.result === 'dead' ? 'falls, dead' : 'goes down, unconscious'}.`
    case 'flee':
      return `${event.name} breaks and flees the field.`
    case 'action': {
      const labels = {
        dodge: 'takes the Dodge action',
        dash: 'dashes',
        disengage: 'disengages',
        stand_up: 'gets back to their feet',
      } as const
      return `${ctx.name(event.id)} ${labels[event.action]}.`
    }
    case 'combat_end':
      return event.winner === 'party' ? 'The last of them goes down. The field is yours.' : 'The party is overwhelmed.'
    case 'combat_start':
    case 'initiative':
    case 'turn_start':
    case 'turn_end':
    case 'edit':
    case 'difficulty':
      return null
  }
}

/** The whole batch an action produced, ready to append as dialogue lines. */
export function recapLines(events: CombatEvent[], ctx: RecapContext): string[] {
  return events.map((e) => recapLine(e, ctx)).filter((line): line is string => line !== null)
}
